Logs:
  Transferred 1 from 0x5615dEB798BB3E4dFa0139dFa1b3D433Cc23b72f to 0xBf0b5A4099F0bf6c8bC4252eBeC548Bae95602Ea

[PASS] testWithdrawERC20_BobBypassSuccess() (gas: 18727)
Logs:
  Transferred 1 from 0x5615dEB798BB3E4dFa0139dFa1b3D433Cc23b72f to 0x4dBa461cA9342F4A6Cf942aBd7eacf8AE259108C

[PASS] testWithdrawERC20_BobFailure() (gas: 12040)
Test result: ok. 3 passed; 0 failed; 0 skipped; finished in 1.11ms
```

## Tools Used
Manual review

## Recommended Mitigation Steps

Add the missing  modifier to the  method:

```diff
diff --git a/src/VirtualAccount.sol b/src/VirtualAccount.sol
index f6a9134..49a679a 100644
--- a/src/VirtualAccount.sol
+++ b/src/VirtualAccount.sol
@@ -82,7 +82,7 @@ contract VirtualAccount is IVirtualAccount, ERC1155Receiver {
     }

     /// @inheritdoc IVirtualAccount
-    function payableCall(PayableCall[] calldata calls) public payable returns (bytes[] memory returnData) {
+    function payableCall(PayableCall[] calldata calls) public payable requiresApprovedCaller returns (bytes[] memory returnData) {
         uint256 valAccumulator;
         uint256 length = calls.length;
         returnData = new bytes[](length);

```



## Assessed type

Access Control

code:
modifier requiresApprovedCaller() {
    if (!IRootPort(localPortAddress).isRouterApproved(this, msg.sender)) {
        if (msg.sender != userAddress) {
            revert UnauthorizedCaller();
        }
    }
    _;
}

function payableCall(PayableCall[] calldata calls) public payable returns (bytes[] memory returnData) {
    uint256 valAccumulator;
    uint256 length = calls.length;
    returnData = new bytes[](length);
    PayableCall calldata _call;
    for (uint256 i = 0; i < length;) {
        _call = calls[i];
        uint256 val = _call.value;
        // Humanity will be a Type V Kardashev Civilization before this overflows - andreas
        // ~ 10^25 Wei in existence << ~ 10^76 size uint fits in a uint256
        unchecked {
            valAccumulator += val;
        }

        bool success;

        if (isContract(_call.target)) (success, returnData[i]) = _call.target.call{value: val}(_call.callData);

        if (!success) revert CallFailed();

        unchecked {
            ++i;
        }
    }

    // Finally, make sure the msg.value = SUM(call[0...i].value)
    if (msg.value != valAccumulator) revert CallFailed();
}

function call(Call[] calldata calls) external override requiresApprovedCaller returns (bytes[] memory returnData) {
    uint256 length = calls.length;
    returnData = new bytes[](length);

    for (uint256 i = 0; i < length;) {
        bool success;
        Call calldata _call = calls[i];

        if (isContract(_call.target)) (success, returnData[i]) = _call.target.call(_call.callData);

        if (!success) revert CallFailed();

        unchecked {
            ++i;
        }
    }
}

function withdrawERC20(address _token, uint256 _amount) external override requiresApprovedCaller {
    _token.safeTransfer(msg.sender, _amount);
}

